/** Estimates to explain: new admissions and changes of ward — GET /api/v1/cost-estimates/worklist (who may call: holders of estimate.view or estimate.prepare or estimate.explain). */
export function worklistCostEstimates(): Promise<EstimateWorkItemOut[]> {
  return api<EstimateWorkItemOut[]>("GET", `/cost-estimates/worklist`, undefined);
}

/** Prepare a cost estimate — POST /api/v1/cost-estimates (who may call: holders of estimate.prepare). */
export function createCostEstimates(body: EstimateIn): Promise<EstimateDetailOut> {
  return api<EstimateDetailOut>("POST", `/cost-estimates`, body, { idempotent: true });
}

/** Cost estimates — GET /api/v1/cost-estimates (who may call: holders of estimate.view or estimate.prepare or estimate.explain). */
export function listEstimates(query?: { admission_id?: number | null; patient_id?: number | null; status?: "Draft" | "Explained" | "Superseded" | "Cancelled" | null; reason?: "Admission" | "ChangeOfWard" | "ChangeOfCondition" | "Procedure" | "OnRequest" | null; limit?: number }): Promise<EstimateOut[]> {
  return api<EstimateOut[]>("GET", withQuery(`/cost-estimates`, query), undefined);
}

/** One cost estimate — GET /api/v1/cost-estimates/{estimate_id} (who may call: holders of estimate.view or estimate.prepare or estimate.explain). */
export function getEstimate(estimate_id: number): Promise<EstimateDetailOut> {
  return api<EstimateDetailOut>("GET", `/cost-estimates/${estimate_id}`, undefined);
}

/** Record that the estimate was explained — POST /api/v1/cost-estimates/{estimate_id}/explain (who may call: holders of estimate.explain). */
export function explain(estimate_id: number, body: EstimateExplainIn): Promise<EstimateDetailOut> {
  return api<EstimateDetailOut>("POST", `/cost-estimates/${estimate_id}/explain`, body, { idempotent: true });
}

/** Cancel an estimate — POST /api/v1/cost-estimates/{estimate_id}/cancel (who may call: holders of estimate.prepare). */
export function cancelCostEstimates(estimate_id: number, body: EstimateCancelIn): Promise<EstimateDetailOut> {
  return api<EstimateDetailOut>("POST", `/cost-estimates/${estimate_id}/cancel`, body, { idempotent: true });
}

/** The estimate to print and sign (A4) — GET /api/v1/cost-estimates/{estimate_id}/print-payload (who may call: holders of estimate.view or estimate.prepare or estimate.explain). */
export function printEstimate(estimate_id: number): Promise<PrintOut_EstimatePrintFieldsOut_> {
  return api<PrintOut_EstimatePrintFieldsOut_>("GET", `/cost-estimates/${estimate_id}/print-payload`, undefined);
}

/** The estimate (PDF, English) — GET /api/v1/cost-estimates/{estimate_id}/pdf (who may call: holders of estimate.view or estimate.prepare or estimate.explain). */
export function estimatePdf(estimate_id: number): Promise<unknown> {
  return api<unknown>("GET", `/cost-estimates/${estimate_id}/pdf`, undefined);
}

/** The tariff: every price, by category — GET /api/v1/tariff (who may call: any logged-in user). */
export function getTariff(): Promise<TariffOut> {
  return api<TariffOut>("GET", `/tariff`, undefined);
}

